#[derive(Clone, Copy)]
enum FormulaFallbackTokenKind {
    Input,
    RandomFunction { random_mode_value: u64 },
}

#[derive(Clone, Copy)]
enum FormulaFallbackGroupShape {
    FormulaOperation {
        operation_value: f32,
    },
    FormulaOperationOperation {
        first_operation_value: f32,
        second_operation_value: f32,
    },
    FormulaOperationOperationOperation {
        first_operation_value: f32,
        second_operation_value: f32,
        third_operation_value: f32,
    },
    OperationFormulaOperation {
        before_operation_value: f32,
        after_operation_value: f32,
    },
    OperationFormulaOperationOperation {
        before_operation_value: f32,
        first_after_operation_value: f32,
        second_after_operation_value: f32,
    },
    OperationOperationFormulaOperation {
        first_before_operation_value: f32,
        second_before_operation_value: f32,
        after_operation_value: f32,
    },
    OperationOperationOperationFormula {
        first_before_operation_value: f32,
        second_before_operation_value: f32,
        third_before_operation_value: f32,
    },
}

impl FormulaFallbackGroupShape {
    fn formula_receives_object_source(self) -> bool {
        matches!(
            self,
            FormulaFallbackGroupShape::FormulaOperation { .. }
                | FormulaFallbackGroupShape::FormulaOperationOperation { .. }
                | FormulaFallbackGroupShape::FormulaOperationOperationOperation { .. }
        )
    }
}

fn push_formula_fallback_converter(bytes: &mut Vec<u8>, token_kind: FormulaFallbackTokenKind) {
    push_object_with_properties(bytes, "DataConverterFormula", |bytes| match token_kind {
        FormulaFallbackTokenKind::Input => {}
        FormulaFallbackTokenKind::RandomFunction { random_mode_value } => {
            if random_mode_value != 0 {
                push_uint_property(
                    bytes,
                    "DataConverterFormula",
                    "randomModeValue",
                    random_mode_value,
                );
            }
        }
    });
    match token_kind {
        FormulaFallbackTokenKind::Input => {
            push_object_with_properties(bytes, "FormulaTokenInput", |_| {});
        }
        FormulaFallbackTokenKind::RandomFunction { .. } => {
            push_object_with_properties(bytes, "FormulaTokenFunction", |bytes| {
                push_uint_property(bytes, "FormulaTokenFunction", "functionType", 16);
            });
            push_object_with_properties(bytes, "FormulaTokenValue", |bytes| {
                push_f32_property(bytes, "FormulaTokenValue", "operationValue", 2.0);
            });
            push_object_with_properties(bytes, "FormulaTokenArgumentSeparator", |_| {});
            push_object_with_properties(bytes, "FormulaTokenValue", |bytes| {
                push_f32_property(bytes, "FormulaTokenValue", "operationValue", 6.0);
            });
            push_object_with_properties(bytes, "FormulaTokenParenthesisClose", |_| {});
        }
    }
}

fn push_operation_value_converter(bytes: &mut Vec<u8>, operation_value: f32) {
    push_object_with_properties(bytes, "DataConverterOperationValue", |bytes| {
        push_uint_property(bytes, "DataConverterOperationValue", "operationType", 0);
        push_f32_property(
            bytes,
            "DataConverterOperationValue",
            "operationValue",
            operation_value,
        );
    });
}

fn push_group_converter_with_items(bytes: &mut Vec<u8>, converter_ids: &[u64]) {
    push_object_with_properties(bytes, "DataConverterGroup", |_| {});
    for converter_id in converter_ids {
        push_object_with_properties(bytes, "DataConverterGroupItem", |bytes| {
            push_uint_property(
                bytes,
                "DataConverterGroupItem",
                "converterId",
                *converter_id,
            );
        });
    }
}

fn push_formula_fallback_group_converter(
    bytes: &mut Vec<u8>,
    group_shape: Option<FormulaFallbackGroupShape>,
) -> u64 {
    match group_shape {
        Some(FormulaFallbackGroupShape::FormulaOperation { operation_value }) => {
            push_operation_value_converter(bytes, operation_value);
            push_group_converter_with_items(bytes, &[0, 1]);
            2
        }
        Some(FormulaFallbackGroupShape::FormulaOperationOperation {
            first_operation_value,
            second_operation_value,
        }) => {
            push_operation_value_converter(bytes, first_operation_value);
            push_operation_value_converter(bytes, second_operation_value);
            push_group_converter_with_items(bytes, &[0, 1, 2]);
            3
        }
        Some(FormulaFallbackGroupShape::FormulaOperationOperationOperation {
            first_operation_value,
            second_operation_value,
            third_operation_value,
        }) => {
            push_operation_value_converter(bytes, first_operation_value);
            push_operation_value_converter(bytes, second_operation_value);
            push_operation_value_converter(bytes, third_operation_value);
            push_group_converter_with_items(bytes, &[0, 1, 2, 3]);
            4
        }
        Some(FormulaFallbackGroupShape::OperationFormulaOperation {
            before_operation_value,
            after_operation_value,
        }) => {
            push_operation_value_converter(bytes, before_operation_value);
            push_operation_value_converter(bytes, after_operation_value);
            push_group_converter_with_items(bytes, &[1, 0, 2]);
            3
        }
        Some(FormulaFallbackGroupShape::OperationFormulaOperationOperation {
            before_operation_value,
            first_after_operation_value,
            second_after_operation_value,
        }) => {
            push_operation_value_converter(bytes, before_operation_value);
            push_operation_value_converter(bytes, first_after_operation_value);
            push_operation_value_converter(bytes, second_after_operation_value);
            push_group_converter_with_items(bytes, &[1, 0, 2, 3]);
            4
        }
        Some(FormulaFallbackGroupShape::OperationOperationFormulaOperation {
            first_before_operation_value,
            second_before_operation_value,
            after_operation_value,
        }) => {
            push_operation_value_converter(bytes, first_before_operation_value);
            push_operation_value_converter(bytes, second_before_operation_value);
            push_operation_value_converter(bytes, after_operation_value);
            push_group_converter_with_items(bytes, &[1, 2, 0, 3]);
            4
        }
        Some(FormulaFallbackGroupShape::OperationOperationOperationFormula {
            first_before_operation_value,
            second_before_operation_value,
            third_before_operation_value,
        }) => {
            push_operation_value_converter(bytes, first_before_operation_value);
            push_operation_value_converter(bytes, second_before_operation_value);
            push_operation_value_converter(bytes, third_before_operation_value);
            push_group_converter_with_items(bytes, &[1, 2, 3, 0]);
            4
        }
        None => 0,
    }
}

fn push_optional_formula_fallback_group_converter(
    bytes: &mut Vec<u8>,
    group_operation_value: Option<f32>,
) -> u64 {
    push_formula_fallback_group_converter(
        bytes,
        group_operation_value
            .map(|operation_value| FormulaFallbackGroupShape::FormulaOperation { operation_value }),
    )
}

fn expected_object_formula_group_random_counts(
    group_shape: FormulaFallbackGroupShape,
    token_kind: FormulaFallbackTokenKind,
    label: &str,
) -> [usize; 2] {
    if group_shape.formula_receives_object_source() {
        return [0, 0];
    }
    match token_kind {
        FormulaFallbackTokenKind::Input => [0, 0],
        FormulaFallbackTokenKind::RandomFunction {
            random_mode_value: 0,
        }
        | FormulaFallbackTokenKind::RandomFunction {
            random_mode_value: 1,
        }
        | FormulaFallbackTokenKind::RandomFunction {
            random_mode_value: 2,
        } => [1, 1],
        FormulaFallbackTokenKind::RandomFunction { random_mode_value } => {
            panic!("{label} unsupported random mode {random_mode_value}")
        }
    }
}

