#[derive(Clone, Copy)]
enum FormulaFallbackSourceKind {
    Enum,
    Color,
    String,
    Trigger,
}

impl FormulaFallbackSourceKind {
    fn label(self) -> &'static str {
        match self {
            Self::Enum => "enum",
            Self::Color => "color",
            Self::String => "string",
            Self::Trigger => "trigger",
        }
    }
}

fn assert_formula_fallback_non_trigger_source_unchanged(
    source_kind: FormulaFallbackSourceKind,
    state_machine: &StateMachineInstance,
    label: &str,
    step: &str,
) {
    match source_kind {
        FormulaFallbackSourceKind::Enum => assert_eq!(
            state_machine.default_view_model_enum_source_value_for_data_bind(0),
            Some(1),
            "{label} {step} enum source mismatch"
        ),
        FormulaFallbackSourceKind::Color => assert_eq!(
            state_machine.default_view_model_color_source_value_for_data_bind(0),
            Some(1),
            "{label} {step} color source mismatch"
        ),
        FormulaFallbackSourceKind::String => assert_eq!(
            state_machine.default_view_model_string_source_value_for_data_bind(0),
            Some(b"1.0suffix".as_slice()),
            "{label} {step} string source mismatch"
        ),
        FormulaFallbackSourceKind::Trigger => {}
    }
}

