fn synthetic_state_machine_default_viewmodel_object_formula_fallback_blend_state_with_token_flags_and_group_shape(
    file_id: u64,
    source_kind: FormulaFallbackObjectSourceKind,
    token_kind: FormulaFallbackTokenKind,
    data_bind_flags: u64,
    group_shape: Option<FormulaFallbackGroupShape>,
) -> Vec<u8> {
    synthetic_runtime_file(file_id, |bytes| {
        push_object_with_properties(bytes, "ViewModel", |bytes| {
            push_string_property(bytes, "ViewModel", "name", "Root");
        });
        match source_kind {
            FormulaFallbackObjectSourceKind::Asset => {
                push_object_with_properties(bytes, "ViewModelPropertyAssetImage", |bytes| {
                    push_string_property(bytes, "ViewModelPropertyAssetImage", "name", "image");
                });
            }
            FormulaFallbackObjectSourceKind::Artboard => {
                push_object_with_properties(bytes, "ViewModelPropertyArtboard", |bytes| {
                    push_string_property(bytes, "ViewModelPropertyArtboard", "name", "scene");
                });
            }
            FormulaFallbackObjectSourceKind::ViewModel => {
                push_object_with_properties(bytes, "ViewModelPropertyViewModel", |bytes| {
                    push_string_property(bytes, "ViewModelPropertyViewModel", "name", "child");
                    push_uint_property(
                        bytes,
                        "ViewModelPropertyViewModel",
                        "viewModelReferenceId",
                        1,
                    );
                });
                push_object_with_properties(bytes, "ViewModel", |bytes| {
                    push_string_property(bytes, "ViewModel", "name", "Child");
                });
            }
        }
        push_object_with_properties(bytes, "Backboard", |_| {});
        push_formula_fallback_converter(bytes, token_kind);
        let converter_id = push_formula_fallback_group_converter(bytes, group_shape);
        push_object_with_properties(bytes, "Artboard", |_| {});
        match source_kind {
            FormulaFallbackObjectSourceKind::Asset => {
                push_object_with_properties(bytes, "ViewModelInstance", |bytes| {
                    push_string_property(bytes, "ViewModelInstance", "name", "root");
                    push_uint_property(bytes, "ViewModelInstance", "viewModelId", 0);
                });
                push_object_with_properties(bytes, "ViewModelInstanceAssetImage", |bytes| {
                    push_uint_property(
                        bytes,
                        "ViewModelInstanceAssetImage",
                        "viewModelPropertyId",
                        0,
                    );
                    push_uint_property(bytes, "ViewModelInstanceAssetImage", "propertyValue", 4);
                });
            }
            FormulaFallbackObjectSourceKind::Artboard => {
                push_object_with_properties(bytes, "ViewModelInstance", |bytes| {
                    push_string_property(bytes, "ViewModelInstance", "name", "root");
                    push_uint_property(bytes, "ViewModelInstance", "viewModelId", 0);
                });
                push_object_with_properties(bytes, "ViewModelInstanceArtboard", |bytes| {
                    push_uint_property(
                        bytes,
                        "ViewModelInstanceArtboard",
                        "viewModelPropertyId",
                        0,
                    );
                    push_uint_property(bytes, "ViewModelInstanceArtboard", "propertyValue", 1);
                });
            }
            FormulaFallbackObjectSourceKind::ViewModel => {
                push_object_with_properties(bytes, "ViewModelInstance", |bytes| {
                    push_string_property(bytes, "ViewModelInstance", "name", "child");
                    push_uint_property(bytes, "ViewModelInstance", "viewModelId", 1);
                });
                push_object_with_properties(bytes, "ViewModelInstance", |bytes| {
                    push_string_property(bytes, "ViewModelInstance", "name", "root");
                    push_uint_property(bytes, "ViewModelInstance", "viewModelId", 0);
                });
                push_object_with_properties(bytes, "ViewModelInstanceViewModel", |bytes| {
                    push_uint_property(
                        bytes,
                        "ViewModelInstanceViewModel",
                        "viewModelPropertyId",
                        0,
                    );
                    push_uint_property(bytes, "ViewModelInstanceViewModel", "propertyValue", 0);
                });
            }
        }
        push_transform_node(bytes, 0, 2.0, 3.0, 1.0, 1.0, 1.0);
        push_animation_for_single_node(bytes, 1, 2.0, 12.0);
        push_animation_for_single_node(bytes, 1, 20.0, 30.0);
        push_object_with_properties(bytes, "StateMachine", |_| {});
        push_object_with_properties(bytes, "StateMachineLayer", |_| {});
        push_object_with_properties(bytes, "AnyState", |_| {});
        push_object_with_properties(bytes, "EntryState", |_| {});
        push_object_with_properties(bytes, "StateTransition", |bytes| {
            push_uint_property(bytes, "StateTransition", "stateToId", 2);
        });
        push_bindable_number_data_bind_context_with_converter_and_flags(
            bytes,
            0.75,
            &[0, 0],
            Some(converter_id),
            data_bind_flags,
        );
        push_object_with_properties(bytes, "BlendState1DViewModel", |_| {});
        push_blend_animation_1d(bytes, 0, 0.0);
        push_blend_animation_1d(bytes, 1, 1.0);
        push_object_with_properties(bytes, "ExitState", |_| {});
    })
}

