fn push_bindable_integer_data_bind(bytes: &mut Vec<u8>, value: u64) {
    push_object_with_properties(bytes, "BindablePropertyInteger", |bytes| {
        push_uint_property(bytes, "BindablePropertyInteger", "propertyValue", value);
    });
    push_object_with_properties(bytes, "DataBind", |_| {});
}

fn push_bindable_integer_data_bind_context_with_flags(
    bytes: &mut Vec<u8>,
    value: u64,
    path: &[u32],
    flags: u64,
) {
    let mut source_path_ids = Vec::new();
    for path_id in path {
        push_var_uint(&mut source_path_ids, u64::from(*path_id));
    }
    push_object_with_properties(bytes, "BindablePropertyInteger", |bytes| {
        push_uint_property(bytes, "BindablePropertyInteger", "propertyValue", value);
    });
    push_object_with_properties(bytes, "DataBindContext", |bytes| {
        push_uint_property(
            bytes,
            "DataBindContext",
            "propertyKey",
            u64::from(property_key_for_name(
                "BindablePropertyInteger",
                "propertyValue",
            )),
        );
        push_bytes_property(bytes, "DataBindContext", "sourcePathIds", &source_path_ids);
        if flags != 0 {
            push_uint_property(bytes, "DataBindContext", "flags", flags);
        }
    });
}

