fn read_cpp_probe_bytes(probe: &Path, label: &str, bytes: &[u8]) -> CppProbeFile {
    read_cpp_probe_bytes_with_args(probe, label, bytes, &[])
}

fn counted_runtime_random_probe_args(values: &[f32], extra_args: &[String]) -> Vec<String> {
    let mut args = vec!["--runtime-random-reset".to_owned()];
    for value in values {
        args.push("--runtime-random-value".to_owned());
        args.push(value.to_string());
    }
    args.extend_from_slice(extra_args);
    args
}

fn read_cpp_probe_bytes_with_args(
    probe: &Path,
    label: &str,
    bytes: &[u8],
    extra_args: &[String],
) -> CppProbeFile {
    let path = cpp_probe_temp_path("rive-rust-runtime", label);
    std::fs::write(&path, bytes)
        .unwrap_or_else(|err| panic!("failed to write {}: {err}", path.display()));

    let output = Command::new(probe)
        .arg("--no-advance")
        .arg("--instance-artboards")
        .arg("--runtime-update")
        .args(extra_args)
        .arg("--file")
        .arg(&path)
        .output()
        .unwrap_or_else(|err| panic!("failed to run {}: {err}", probe.display()));

    assert!(
        output.status.success(),
        "C++ probe failed for {label}\npath: {}\nstatus: {}\nstdout:\n{}\nstderr:\n{}",
        path.display(),
        output.status,
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );

    if std::env::var_os("RIVE_KEEP_CPP_PROBE_FIXTURES").is_some() {
        eprintln!("kept C++ probe fixture for {label}: {}", path.display());
    } else {
        let _ = std::fs::remove_file(&path);
    }

    serde_json::from_slice(&output.stdout)
        .unwrap_or_else(|err| panic!("invalid probe JSON for {label}: {err}"))
}

fn cpp_probe_accepts_bytes(probe: &Path, label: &str, bytes: &[u8]) -> bool {
    let path = cpp_probe_temp_path("rive-rust-runtime", label);
    std::fs::write(&path, bytes)
        .unwrap_or_else(|err| panic!("failed to write {}: {err}", path.display()));
    let status = Command::new(probe)
        .arg("--no-advance")
        .arg("--instance-artboards")
        .arg("--file")
        .arg(&path)
        .status()
        .unwrap_or_else(|err| panic!("failed to run {}: {err}", probe.display()));
    let _ = std::fs::remove_file(path);
    status.success()
}

fn rust_accepts_artboard_instance(bytes: &[u8]) -> bool {
    let Ok(runtime) = read_runtime_file(bytes) else {
        return false;
    };
    let Ok(graph) = GraphFile::from_runtime_file(&runtime) else {
        return false;
    };
    graph
        .artboards
        .first()
        .is_some_and(|artboard| ArtboardInstance::from_graph(&runtime, artboard).is_ok())
}

fn read_rust_instance_from_bytes(bytes: &[u8], label: &str) -> (RuntimeFile, ArtboardInstance) {
    let (runtime, _graph, instance) = read_rust_graph_instance_from_bytes(bytes, label);
    (runtime, instance)
}

fn read_rust_graph_instance_from_bytes(
    bytes: &[u8],
    label: &str,
) -> (RuntimeFile, GraphFile, ArtboardInstance) {
    let runtime = read_runtime_file(bytes).unwrap_or_else(|err| {
        panic!("failed to import {label}: {err:#}");
    });
    let graph = GraphFile::from_runtime_file(&runtime).unwrap_or_else(|err| {
        panic!("failed to build Rust graph for {label}: {err:#}");
    });
    let artboard = graph
        .artboards
        .first()
        .unwrap_or_else(|| panic!("missing Rust artboard for {label}"));
    let instance =
        ArtboardInstance::from_graph_with_artboards(&runtime, artboard, &graph.artboards)
            .unwrap_or_else(|err| {
                panic!("failed to build Rust artboard instance for {label}: {err:#}");
            });

    (runtime, graph, instance)
}

#[test]
fn data_context_file_backed_lookup_reports_match_cpp_probe() {
    let Some(probe) = probe_path() else {
        eprintln!("skipping C++ runtime comparison; set RIVE_CPP_PROBE to enable");
        return;
    };

    let label = "data-context-nested-viewmodel-lookup";
    let bytes = synthetic_data_context_nested_viewmodel_lookup(89601);
    let args = vec!["--data-context-lookups".to_owned()];
    let cpp = read_cpp_probe_bytes_with_args(&probe, label, &bytes, &args);
    let rust = read_runtime_file(&bytes).unwrap_or_else(|err| {
        panic!("failed to import {label}: {err:#}");
    });

    let cpp_reports = cpp
        .data_context_lookups
        .iter()
        .map(comparable_data_context_lookup_from_cpp)
        .collect::<Vec<_>>();
    let rust_reports = runtime_data_context_lookup_reports(&rust)
        .iter()
        .map(comparable_data_context_lookup_from_runtime)
        .collect::<Vec<_>>();

    assert_eq!(cpp_reports, rust_reports, "{label} lookup report mismatch");
}

#[test]
fn runtime_data_context_covers_absolute_and_unresolved_relative_parent_paths() {
    let label = "data-context-runtime-resolver";
    let bytes = synthetic_data_context_nested_viewmodel_lookup(89602);
    let rust = read_runtime_file(&bytes).unwrap_or_else(|err| {
        panic!("failed to import {label}: {err:#}");
    });

    let root_context = RuntimeDataContext::new(&rust, 0, 0)
        .unwrap_or_else(|| panic!("missing root data context for {label}"));
    let child_context = RuntimeDataContext::new(&rust, 1, 0)
        .unwrap_or_else(|| panic!("missing child data context for {label}"));
    let root_with_child_parent = root_context.clone().with_parent(&child_context);

    let absolute_child = root_context
        .absolute_property_ref(&[0, 0])
        .unwrap_or_else(|| panic!("missing absolute child property for {label}"));
    assert_eq!(
        (
            absolute_child.view_model_index,
            absolute_child.name.as_str()
        ),
        (0, "child"),
        "{label} absolute child property mismatch"
    );

    let absolute_root_instance = root_context
        .absolute_instance_ref(&[0])
        .unwrap_or_else(|| panic!("missing absolute root instance for {label}"));
    assert_eq!(
        (
            absolute_root_instance.view_model_index,
            absolute_root_instance.name.as_str()
        ),
        (0, "root-instance"),
        "{label} absolute root instance mismatch"
    );

    assert_eq!(
        root_context.property_from_path_ref(&[0, 0]),
        None,
        "{label} propertyFromPath should preserve unresolved nested amount boundary"
    );
    assert_eq!(
        root_context.relative_property_ref(&[77, 78]),
        None,
        "{label} relative lookup should preserve unresolved nested amount boundary"
    );

    assert_eq!(
        root_context.relative_property_ref(&[77]),
        None,
        "{label} relative child property should preserve unresolved name boundary"
    );

    assert_eq!(
        root_with_child_parent.parent_instances().len(),
        1,
        "{label} parent chain length mismatch"
    );
    assert_eq!(
        root_with_child_parent.relative_property_ref(&[78]),
        None,
        "{label} parent-fallback should preserve unresolved amount boundary"
    );

    assert_eq!(
        root_context.relative_instance_ref(&[77]),
        None,
        "{label} relative child instance should preserve unresolved reference boundary"
    );
}

#[test]
fn runtime_update_matches_cpp_for_transform_hierarchy() {
    let Some(probe) = probe_path() else {
        eprintln!("skipping C++ runtime comparison; set RIVE_CPP_PROBE to enable");
        return;
    };

    let label = "synthetic/runtime_transform_hierarchy.riv";
    let bytes = synthetic_transform_hierarchy();
    let cpp = read_cpp_probe_bytes(&probe, label, &bytes);
    let (_, mut rust) = read_rust_instance_from_bytes(&bytes, label);
    let report = rust.update_components();

    let cpp_artboard = cpp
        .artboards
        .first()
        .unwrap_or_else(|| panic!("missing C++ artboard for {label}"));
    let cpp_update = cpp_artboard
        .runtime_update
        .as_ref()
        .unwrap_or_else(|| panic!("missing C++ runtimeUpdate for {label}"));

    assert_eq!(cpp_artboard.object_count, rust.slots().len());
    assert_eq!(cpp_artboard.objects.len(), rust.slots().len());
    for (local_id, (cpp_object, rust_slot)) in
        cpp_artboard.objects.iter().zip(rust.slots()).enumerate()
    {
        assert_eq!(rust_slot.local_id, local_id);
        match (cpp_object, rust_slot.type_name) {
            (Some(cpp_object), Some(type_name)) => {
                assert_eq!(cpp_object.local_id, local_id);
                assert_eq!(
                    cpp_object.core_type,
                    type_key_for_name(type_name),
                    "slot core type mismatch for local {local_id} in {label}"
                );
                assert_eq!(cpp_object.is_component, rust.component(local_id).is_some());
            }
            (None, None) => {}
            _ => panic!("slot presence mismatch for local {local_id} in {label}"),
        }
    }

    assert_eq!(cpp_update.did_update, report.did_update);
    assert_eq!(
        cpp_update.has_components_dirt,
        rust.has_dirt(ComponentDirt::COMPONENTS)
    );

    for cpp_component in &cpp_update.components {
        let rust_component = rust
            .component(cpp_component.local_id)
            .unwrap_or_else(|| panic!("missing Rust component {}", cpp_component.local_id));
        compare_component(cpp_component, rust_component, label);
    }
}

