fn infer_formula_random_value_from_cpp_number_binding(
    cpp_artboard: &CppArtboard,
    report_index: usize,
    data_bind_index: usize,
    lower_bound: f32,
    upper_bound: f32,
    label: &str,
) -> f32 {
    let target_value = cpp_artboard
        .runtime_state_machine_advances
        .get(report_index)
        .and_then(|advance| {
            advance
                .number_bindings
                .iter()
                .find(|binding| binding.data_bind_index == data_bind_index)
        })
        .and_then(|binding| binding.target_value)
        .unwrap_or_else(|| panic!("missing C++ random formula target value for {label}"));
    (target_value - lower_bound) / (upper_bound - lower_bound)
}

fn infer_formula_random_value_from_cpp_number_binding_scaled_target(
    cpp_artboard: &CppArtboard,
    report_index: usize,
    data_bind_index: usize,
    target_scale: f32,
    lower_bound: f32,
    upper_bound: f32,
    label: &str,
) -> f32 {
    let target_value = cpp_artboard
        .runtime_state_machine_advances
        .get(report_index)
        .and_then(|advance| {
            advance
                .number_bindings
                .iter()
                .find(|binding| binding.data_bind_index == data_bind_index)
        })
        .and_then(|binding| binding.target_value)
        .unwrap_or_else(|| panic!("missing C++ random formula target value for {label}"));
    (target_value * target_scale - lower_bound) / (upper_bound - lower_bound)
}

