#[test]
fn state_machine_default_viewmodel_object_formula_fallbacks_main_to_target_two_way_target_dirty_matches_cpp_probe()
 {
    const DATA_BIND_TWO_WAY: u64 = 1 << 1;

    let Some(probe) = probe_path() else {
        eprintln!("skipping C++ runtime comparison; set RIVE_CPP_PROBE to enable");
        return;
    };

    let cases = [
        FormulaFallbackObjectSourceKind::Asset,
        FormulaFallbackObjectSourceKind::Artboard,
        FormulaFallbackObjectSourceKind::ViewModel,
    ];

    for (case_index, source_kind) in cases.iter().copied().enumerate() {
        let label = format!(
            "synthetic/runtime_state_machine_default_viewmodel_{}_formula_fallback_target_dirty_cpp.riv",
            source_kind.label()
        );
        let bytes =
            synthetic_state_machine_default_viewmodel_object_formula_fallback_blend_state_with_flags(
                9350 + case_index as u64,
                source_kind,
                DATA_BIND_TWO_WAY,
            );
        let args = [
            "--runtime-bind-default-view-model-state-machine-context".to_owned(),
            "0".to_owned(),
            "--runtime-advance-state-machine".to_owned(),
            "0".to_owned(),
            "0".to_owned(),
            "--runtime-set-state-machine-bindable-number".to_owned(),
            "0".to_owned(),
            "0".to_owned(),
            "0.4".to_owned(),
            "--runtime-advance-state-machine-data-context".to_owned(),
            "0".to_owned(),
            "--runtime-advance-state-machine".to_owned(),
            "0".to_owned(),
            "0".to_owned(),
            "--runtime-advance-state-machine".to_owned(),
            "0".to_owned(),
            "1".to_owned(),
        ];

        let cpp = read_cpp_probe_bytes_with_args(&probe, &label, &bytes, &args);
        let (_, mut rust) = read_rust_instance_from_bytes(&bytes, &label);
        let mut state_machine = rust
            .state_machine_instance(0)
            .unwrap_or_else(|| panic!("missing Rust state-machine instance for {label}"));

        let mut rust_reports = Vec::new();
        assert!(
            state_machine.bind_default_view_model_context(),
            "{label} failed to bind default view-model context"
        );
        rust_reports.push((
            rust.advance_state_machine_instance(&mut state_machine, 0.0),
            state_machine.clone(),
        ));
        assert!(
            state_machine.set_bindable_number_for_data_bind(0, 0.4),
            "{label} failed to mutate bindable number"
        );
        assert!(
            state_machine.advance_data_context(),
            "{label} failed to advance target-dirty data context"
        );
        rust_reports.push((false, state_machine.clone()));
        rust_reports.push((
            rust.advance_state_machine_instance(&mut state_machine, 0.0),
            state_machine.clone(),
        ));
        rust_reports.push((
            rust.advance_state_machine_instance(&mut state_machine, 1.0),
            state_machine.clone(),
        ));
        let report = rust.update_components();

        let cpp_artboard = cpp
            .artboards
            .first()
            .unwrap_or_else(|| panic!("missing C++ artboard for {label}"));
        assert_eq!(
            cpp_artboard.runtime_state_machine_advances.len(),
            rust_reports.len(),
            "{label} state-machine report count mismatch"
        );
        for (step, (cpp_state_machine, (advanced, rust_state_machine))) in cpp_artboard
            .runtime_state_machine_advances
            .iter()
            .zip(&rust_reports)
            .enumerate()
        {
            let step_label = format!("{label} action {step}");
            compare_state_machine_advance(
                cpp_state_machine,
                rust_state_machine,
                *advanced,
                &step_label,
            );
            compare_state_machine_number_binding(
                cpp_state_machine,
                rust_state_machine,
                0,
                &step_label,
            );
        }
        compare_cpp_runtime_update(&cpp, &rust, &report, &label);
    }
}

