#[test]
fn state_machine_default_viewmodel_random_formula_fallbacks_match_cpp_probe() {
    let Some(probe) = probe_path() else {
        eprintln!("skipping C++ runtime comparison; set RIVE_CPP_PROBE to enable");
        return;
    };

    #[derive(Clone, Copy)]
    enum RandomFormulaFallbackCase {
        Boolean,
        Other(FormulaFallbackSourceKind),
    }

    impl RandomFormulaFallbackCase {
        fn label(self) -> &'static str {
            match self {
                Self::Boolean => "boolean",
                Self::Other(source_kind) => source_kind.label(),
            }
        }

        fn bytes(self, file_id: u64, random_mode_value: u64) -> Vec<u8> {
            let token_kind = FormulaFallbackTokenKind::RandomFunction { random_mode_value };
            match self {
                Self::Boolean => {
                    synthetic_state_machine_default_viewmodel_boolean_formula_fallback_blend_state_with_token(
                        file_id,
                        token_kind,
                    )
                }
                Self::Other(source_kind) => {
                    synthetic_state_machine_default_viewmodel_formula_fallback_blend_state_with_token(
                        file_id,
                        source_kind,
                        token_kind,
                    )
                }
            }
        }
    }

    let cases = [
        RandomFormulaFallbackCase::Boolean,
        RandomFormulaFallbackCase::Other(FormulaFallbackSourceKind::Enum),
        RandomFormulaFallbackCase::Other(FormulaFallbackSourceKind::Color),
        RandomFormulaFallbackCase::Other(FormulaFallbackSourceKind::String),
        RandomFormulaFallbackCase::Other(FormulaFallbackSourceKind::Trigger),
    ];
    let random_modes = [0, 1, 2];

    for (case_index, case) in cases.iter().copied().enumerate() {
        for random_mode_value in random_modes {
            let label = format!(
                "synthetic/runtime_state_machine_default_viewmodel_{}_formula_random_fallback_mode_{}_cpp.riv",
                case.label(),
                random_mode_value
            );
            let bytes = case.bytes(
                8608 + (case_index as u64 * 3) + random_mode_value,
                random_mode_value,
            );
            let args = [
                "--runtime-bind-default-view-model-state-machine-context".to_owned(),
                "0".to_owned(),
                "--runtime-advance-state-machine".to_owned(),
                "0".to_owned(),
                "0".to_owned(),
                "--runtime-advance-state-machine".to_owned(),
                "0".to_owned(),
                "1".to_owned(),
            ];

            let seeded_random_values = [0.875_f32, 0.625];
            let expected_counts = [0_usize, 0];
            let probe_args = counted_runtime_random_probe_args(&seeded_random_values, &args);
            let cpp = read_cpp_probe_bytes_with_args(&probe, &label, &bytes, &probe_args);
            let (_, mut rust) = read_rust_instance_from_bytes(&bytes, &label);
            let mut state_machine = rust
                .state_machine_instance(0)
                .unwrap_or_else(|| panic!("missing Rust state-machine instance for {label}"));

            assert!(
                state_machine.bind_default_view_model_context(),
                "{label} failed to bind default view-model context"
            );
            state_machine.set_data_bind_formula_random_values(&seeded_random_values);
            assert_formula_random_call_count(&state_machine, 0, &label, "after random reset");
            let mut rust_reports = Vec::new();
            rust_reports.push((
                rust.advance_state_machine_instance(&mut state_machine, 0.0),
                state_machine.clone(),
            ));
            assert_formula_random_call_count(&state_machine, 0, &label, "after first advance");
            rust_reports.push((
                rust.advance_state_machine_instance(&mut state_machine, 1.0),
                state_machine.clone(),
            ));
            assert_formula_random_call_count(&state_machine, 0, &label, "after second advance");
            let report = rust.update_components();

            let cpp_artboard = cpp
                .artboards
                .first()
                .unwrap_or_else(|| panic!("missing C++ artboard for {label}"));
            assert_eq!(
                cpp_artboard.runtime_state_machine_advances.len(),
                rust_reports.len(),
                "{label} state-machine report count mismatch"
            );
            for (index, (cpp_state_machine, (advanced, rust_state_machine))) in cpp_artboard
                .runtime_state_machine_advances
                .iter()
                .zip(&rust_reports)
                .enumerate()
            {
                compare_state_machine_advance(
                    cpp_state_machine,
                    rust_state_machine,
                    *advanced,
                    &label,
                );
                assert_eq!(
                    cpp_state_machine.random_total_calls, expected_counts[index],
                    "{label} C++ random totalCalls mismatch at report {index}"
                );
                assert_eq!(
                    cpp_state_machine.random_total_calls,
                    rust_state_machine.data_bind_formula_random_call_count(),
                    "{label} C++ and Rust random call count mismatch at report {index}"
                );
            }
            compare_cpp_runtime_update(&cpp, &rust, &report, &label);
        }
    }
}

