#[test]
fn state_machine_viewmodel_enum_conditions_match_cpp_probe() {
    let Some(probe) = probe_path() else {
        eprintln!("skipping C++ runtime comparison; set RIVE_CPP_PROBE to enable");
        return;
    };

    for (label, bytes, bind_context, mutated_value) in [
        (
            "synthetic/runtime_state_machine_viewmodel_enum_condition_no_context_cpp.riv",
            synthetic_state_machine_viewmodel_enum_condition(8298, 7, 7, 0),
            false,
            None,
        ),
        (
            "synthetic/runtime_state_machine_viewmodel_enum_condition_static_equal_cpp.riv",
            synthetic_state_machine_viewmodel_enum_condition(8299, 7, 7, 0),
            true,
            None,
        ),
        (
            "synthetic/runtime_state_machine_viewmodel_enum_condition_mutated_equal_cpp.riv",
            synthetic_state_machine_viewmodel_enum_condition(8300, 3, 7, 0),
            true,
            Some(7),
        ),
        (
            "synthetic/runtime_state_machine_viewmodel_enum_condition_static_not_equal_cpp.riv",
            synthetic_state_machine_viewmodel_enum_condition(8301, 3, 7, 1),
            true,
            None,
        ),
        (
            "synthetic/runtime_state_machine_viewmodel_enum_condition_ordered_false_cpp.riv",
            synthetic_state_machine_viewmodel_enum_condition(8302, 3, 7, 4),
            true,
            None,
        ),
    ] {
        let mut args = vec![
            "--runtime-advance-state-machine".to_owned(),
            "0".to_owned(),
            "0".to_owned(),
        ];
        if bind_context {
            args.extend([
                "--runtime-bind-empty-state-machine-context".to_owned(),
                "0".to_owned(),
            ]);
        }
        if let Some(value) = mutated_value {
            args.extend([
                "--runtime-set-state-machine-bindable-enum".to_owned(),
                "0".to_owned(),
                "0".to_owned(),
                value.to_string(),
            ]);
        }
        args.extend([
            "--runtime-advance-state-machine".to_owned(),
            "0".to_owned(),
            "0".to_owned(),
            "--runtime-advance-state-machine".to_owned(),
            "0".to_owned(),
            "1".to_owned(),
        ]);

        let cpp = read_cpp_probe_bytes_with_args(&probe, label, &bytes, &args);
        let (_, mut rust) = read_rust_instance_from_bytes(&bytes, label);
        let mut state_machine = rust
            .state_machine_instance(0)
            .unwrap_or_else(|| panic!("missing Rust state-machine instance for {label}"));

        let mut rust_reports = Vec::new();
        rust_reports.push((
            rust.advance_state_machine_instance(&mut state_machine, 0.0),
            state_machine.clone(),
        ));
        if bind_context {
            assert!(
                state_machine.bind_empty_data_context(),
                "{label} failed to bind empty data context"
            );
        }
        if let Some(value) = mutated_value {
            assert!(
                state_machine.set_bindable_enum_for_data_bind(0, value),
                "{label} failed to mutate bindable enum"
            );
        }
        rust_reports.push((
            rust.advance_state_machine_instance(&mut state_machine, 0.0),
            state_machine.clone(),
        ));
        rust_reports.push((
            rust.advance_state_machine_instance(&mut state_machine, 1.0),
            state_machine.clone(),
        ));
        let report = rust.update_components();

        let cpp_artboard = cpp
            .artboards
            .first()
            .unwrap_or_else(|| panic!("missing C++ artboard for {label}"));
        assert_eq!(
            cpp_artboard.runtime_state_machine_advances.len(),
            rust_reports.len(),
            "{label} state-machine report count mismatch"
        );
        for (cpp_state_machine, (advanced, rust_state_machine)) in cpp_artboard
            .runtime_state_machine_advances
            .iter()
            .zip(&rust_reports)
        {
            compare_state_machine_advance(cpp_state_machine, rust_state_machine, *advanced, label);
        }
        compare_cpp_runtime_update(&cpp, &rust, &report, label);
    }
}

